def cinema():
    corn = ''.join(C(x, y, r, '#fff6dc', 3) + HL('M%s %s q4 -4 8 -2' % (x - 5, y - 3), .7, 2.5) for x, y, r in [(86, 84, 15), (110, 70, 17), (136, 66, 17), (160, 74, 16), (178, 92, 14), (98, 100, 14), (124, 92, 16), (152, 98, 15), (136, 112, 13)])
