    a = corn + box + ticket(60, 196, -16, '#ffd23f') + ticket(62, 220, 8, '#ff8a4a') + clap
    return build(rrect_d(26, 22, 204, 212, 64), ('#ff7a8a', '#b8203a'), a, star(206, 46, 10, '#ffe9a8') + star(44, 52, 8, '#ffe9a8'), -5)


