def board_game():
    king = G(P('M-18 40 H18 L14 14 Q24 -2 6 -16 H-6 Q-24 -2 -14 14Z', '#fff6e2') + R(-22, 40, 44, 10, 4, '#e8d8b8', 3.4) + R(-3, -36, 6, 22, 2, '#fff6e2', 3) + R(-10, -30, 20, 6, 2, '#fff6e2', 3) + HL('M-8 8 v22', .6, 3), -6, 80, 118, 1.05)
