    die = lambda x, y, r, pips: G(R(-22, -22, 44, 44, 9, '#fff', 3.4) + dots(pips, 4.4, INK), r, x, y)
    cards = G(R(-26, -36, 52, 72, 6, '#fff', 3.2, -22) + R(-26, -36, 52, 72, 6, '#fff', 3.2, -4) + R(-26, -36, 52, 72, 6, '#fff', 3.2, 14) + star(0, 0, 14, '#d8283a', .95) , 0, 190, 90, .9)
